package org.firstinspires.ftc.teamcode.auto;

import com.pedropathing.math.Pose;

/**
 * Shared RED auto poses on the BIOBUZZ field (see FieldGeometry for the frame). Blue is
 * generated by rotation in AutoBase. Measured from the manual's figures - TODO(measure) on a
 * real field; nudge here and every auto picks it up.
 *
 * <p>Robot assumed ~18 in square, so "touching a wall" = centre 9 in from it.</p>
 */
final class FieldPoses {
    private FieldPoses() {
    }

    private static Pose pose(double x, double y, double headingDeg) {
        return new Pose(x, y, Math.toRadians(headingDeg));
    }

    // Starts: touching our wall, on our half, NOT in the loading zone or a flower (G304).
    static final Pose START_RED_WALL = pose(9, 84, 0);       // red wall, between flower and loading zone
    static final Pose START_AUDIENCE_WALL = pose(40, 9, 90);  // audience wall, right of the garden
    static final Pose START_FAR_WALL = pose(24, 135, -90);    // far wall, left of the far flower

    // Shooting spots with a clear view of both of our cells (cells at x 59, y 61 / 83).
    static final Pose SHOOT_CENTER = pose(30, 72, 0);
    static final Pose SHOOT_LOW = pose(30, 40, 45);

    // POLLEN pickups on our half.
    static final Pose GARDEN_LINE_UP = pose(36, 10, 180);    // red GARDEN: 4 POLLEN along the audience wall
    static final Pose GARDEN_END = pose(14, 10, 180);
    static final Pose WALL_FLOWER_LINE_UP = pose(26, 48, 180); // FLOWER on the red wall (retrieval opening at its base)
    static final Pose WALL_FLOWER = pose(13, 48, 180);
    static final Pose FAR_FLOWER_LINE_UP = pose(48, 118, 90);  // FLOWER on the far wall
    static final Pose FAR_FLOWER = pose(48, 131, 90);

    /**
     * PARK (5 pts): partly inside the red LOADING ZONE (x 0..11, y ~96..119) but clear of the
     * wall, so LEAVE (3 pts, "not contacting the perimeter wall") still counts at end of AUTO.
     */
    static final Pose PARK = pose(14, 108, 0);
}
